variables.body:
if (!$ctrl.primaryEntity) return;

// --- 1. Set Initial UI State ---
$ctrl.currentPage = page ?? $ctrl.currentPage;
$ctrl.isLoading = true;
$ctrl.displayTable = false;
$ctrl.tableData.length = 0;
$ctrl.selectedRows.length = 0;

const limit = null;
const targetEntityType = $ctrl.targetEntityType;

try {
    if (targetEntityType === 'role') {
        const isAssigning = $ctrl.currentAction?.buttonLabel === "ASSIGN";
        const primaryEntityId = $ctrl.primaryEntity?.id;

        if (!primaryEntityId) {
            throw new Error("A primary entity (like a user) must be selected to assign roles.");
        }

        // const [allRoles, allTenants, allUserRolesResponse] = await Promise.all([
        //     $ctrl.entityService.getAllEntities(1, limit, null, false, 'role', 'auth'),
        //     $ctrl.entityService.getAllEntities(1, limit, null, false, 'tenant', 'auth'),
        //     $ctrl.entityService.getAllEntities(1, limit, null, false, 'user_role', 'auth')
        // ]);

        // Use the options object for API calls and destructure the 'entities' from each response.
        const [rolesResponse, tenantsResponse, userRolesResponse] = await Promise.all([
            $ctrl.entityService.getAllEntities({ entity: 'role', apiType: 'auth', limit: limit }),
            $ctrl.entityService.getAllEntities({ entity: 'tenant', apiType: 'auth', limit: limit }),
            $ctrl.entityService.getAllEntities({ entity: 'user_role', apiType: 'auth', limit: limit, customEntityKey: 'userrole' })
        ]);

        const allRoles = rolesResponse.entities || [];
        const allTenants = tenantsResponse.entities || [];
        const allUserRoleAssignments = userRolesResponse.entities || [];

        $ctrl.currentTenantMenuItems = allTenants.map(tenant => ({
            label: tenant.name,
            evaluateLabel: false,
            onClick: "function",
            function: () => $ctrl.onTargetTenantChange(tenant)
        }));

        // Safely set a default target tenant if one isn't selected
        if (!$ctrl.targetTenant?.id && allTenants.length > 0) {
            const firstTenant = allTenants[0];
            $ctrl.targetTenant.id = firstTenant.id;
            $ctrl.targetTenant.name = firstTenant.name;
        }

        if (!$ctrl.targetTenant?.id) {
            $ctrl.tableData = []; // No tenants exist, show an empty table
            return;
        }
        const targetTenantId = $ctrl.targetTenant.id;

        const roleMap = new Map(allRoles.map(role => [role.id, role]));

        // Filter for the primary entity FIRST
        const primaryEntityRoles = allUserRoleAssignments.filter(ur => ur.userId === primaryEntityId);
        const existingRoleSet = new Set(primaryEntityRoles.map(ur => `${ur.roleId}-${ur.tenantId}`));

        let rolesToDisplay = [];

        if (isAssigning) {
            // For ASSIGN, create all role combinations for the SELECTED tenant
            const possibleCombinations = allRoles.map(role => ({
                roleId: role.id,
                tenantId: targetTenantId
            }));
            // Only show combinations that the user does not already have
            rolesToDisplay = possibleCombinations.filter(combo =>
                !existingRoleSet.has(`${combo.roleId}-${combo.tenantId}`)
            );
        } else { // For UNASSIGN
            // Show only the roles the primary entity has for the SELECTED tenant
            rolesToDisplay = primaryEntityRoles.filter(ur => ur.tenantId === targetTenantId);
        }

        // Enrich and create final table data
        $ctrl.tableData = rolesToDisplay.map(role => {
            // Get the full role object from our map
            const fullRole = roleMap.get(role.roleId);

            return {
                id: role.id,
                roleId: role.roleId,
                tenantId: role.tenantId,
                name: fullRole ? fullRole.name : 'Unknown Role',
                description: fullRole ? fullRole.description : '',
                tenantName: $ctrl.targetTenant.name
            };
        });

    } else if (targetEntityType === 'scope') {
        const isAssigning = $ctrl.currentAction?.buttonLabel === "ASSIGN";
        const primaryEntityId = $ctrl.primaryEntity?.id; // The selected ROLE's ID

        if (!primaryEntityId) {
            throw new Error("A primary entity (a role) must be selected to assign scopes.");
        }

        // const [allScopesResponse, allRoleScopesResponse] = await Promise.all([
        //     $ctrl.entityService.getAllEntities(1, limit, null, false, 'scope', 'auth'),
        //     $ctrl.entityService.getAllEntities(1, limit, null, false, 'role_scope', 'auth')
        // ]);

          const [scopesResponse, roleScopesResponse] = await Promise.all([
                $ctrl.entityService.getAllEntities({ entity: 'scope', apiType: 'auth', limit: limit }),
                $ctrl.entityService.getAllEntities({ entity: 'role_scope', apiType: 'auth', limit: limit, customEntityKey: 'rolescope' })
            ]);

        const allScopes = scopesResponse.entities || [];
        const allRoleScopeAssignments = roleScopesResponse.entities || [];

        // const allScopes = allScopesResponse || [];
        // const allRoleScopeAssignments = allRoleScopesResponse.rolescope || [];

        const assignedRoleScopes = allRoleScopeAssignments.filter(
            assignment => assignment.roleId === primaryEntityId
        );

        const scopeMap = new Map(allScopes.map(scope => [scope.id, scope]));

        // --- 1. REVISED: Create a more specific Set of existing scope-permission pairs ---
        // Instead of just scope IDs, we store a composite key like "scopeId-permission".
        const existingScopePermissionSet = new Set(
            assignedRoleScopes.map(rs => `${rs.scopeId}-${rs.permission}`)
        );

        let scopesToDisplay = [];

        if (isAssigning) {
            // You must have a permission selected to know what you are assigning.
            if (!$ctrl.currentScopePermission) {
                scopesToDisplay = [];
                console.warn("No permission selected. Cannot show scopes to assign.");
            } else {
                // --- 2. REVISED: Filter based on the specific scope-permission combination ---
                // Now we filter out a scope only if it's already assigned with the
                // currently selected permission.
                scopesToDisplay = allScopes.filter(scope =>
                    !existingScopePermissionSet.has(`${scope.id}-${$ctrl.currentScopePermission}`)
                );
            }

        } else { // For UNASSIGN, the existing logic is still correct.
            let assignedScopesToFilter = assignedRoleScopes;

            if ($ctrl.currentScopePermission) {
                assignedScopesToFilter = assignedScopesToFilter.filter(
                    assignment => assignment.permission === $ctrl.currentScopePermission
                );
            }

            scopesToDisplay = assignedScopesToFilter.map(assignment => {
                const scopeDetails = scopeMap.get(assignment.scopeId) || {};
                return {
                    ...assignment,
                    apiEndpoint: scopeDetails.apiEndpoint,
                    description: scopeDetails.description
                };
            });
        }

        $ctrl.tableData = scopesToDisplay;
    } else {
        const entities = await $ctrl.entityService.getAllEntities(page, limit, query, clearCache, targetEntityType, 'auth');
        $ctrl.tableData = entities;
    }

    $ctrl.displayTable = true;

} catch (error) {
    console.error(`Error fetching entities for '${targetEntityType}':`, error);
    $ctrl.utilityService.toast("Failed to load data. Please try again.", "ERROR");
} finally {
    $ctrl.isLoading = false;
}

$ctrl.currentFilter.column = newColumnValue ?? $ctrl.currentFilter.column;
$ctrl.currentFilter.operation = newOperationValue ?? $ctrl.currentFilter.operation;
$ctrl.currentFilter.target = newTargetValue ?? $ctrl.currentFilter.target;

if (newTargetValue === "") {
    $ctrl.currentFilter.query = undefined;
    $ctrl.loadData(undefined, undefined, undefined, undefined);
}

if (!($ctrl.currentFilter.column && $ctrl.currentFilter.operation && $ctrl.currentFilter.target)) return;

$ctrl.currentFilter.query = buildFilterQuery($ctrl.currentFilter);

$ctrl.loadData(undefined, undefined, $ctrl.currentFilter.query, undefined);

function buildFilterQuery(currentFilter) {
    if (!currentFilter || !currentFilter.column || !currentFilter.target || !currentFilter.operation) {
        return '';
    }

    const { column, target, operation } = currentFilter;
    let apiOperation = operation;

    return `${column}_${apiOperation}=${target}`;
}

// --- 1. Set Initial State ---
$ctrl.isAssigning = true;
$ctrl.successfulAssignments.length = 0;
$ctrl.failedAssignments.length = 0;
$ctrl.hasOperationCompleted = true; // Indicate that an operation has been run

// --- 2. Get Key Information ---
const options = {
    apiType: "auth"
};

const deleteOptions = {
    apiType: "auth",
    skipModal: true
};

const targetEntityType = $ctrl.targetEntityType;
const actionLabel = $ctrl.currentAction?.buttonLabel; // Should be "ASSIGN" or "UNASSIGN"
const primaryEntityId = $ctrl.primaryEntity?.id;

if (!primaryEntityId) {
    $ctrl.utilityService.toast("No primary entity (e.g., user) selected.", "ERROR");
    $ctrl.isAssigning = false;
    return;
}
if ($ctrl.selectedRows.length === 0) {
    $ctrl.utilityService.toast("Please select one or more roles to proceed.", "INFO");
    $ctrl.isAssigning = false;
    return;
}

try {
    if (targetEntityType === "role") {
        // --- 3. Loop Through Each Selected Role ---
        for (const row of $ctrl.selectedRows) {
            const nameForDisplay = row.name || "Unknown Name";
            let response;

            // --- 4. Perform Action based on the Button Label ---
            if (actionLabel === "ASSIGN") {
                // Construct the body to create a new user_role link
                const requestBody = {
                    userId: primaryEntityId,
                    roleId: row.roleId,
                    tenantId: row.tenantId
                };

                response = await $ctrl.dataService.sendData('user_role', 'POST', requestBody, options);

            } else if (actionLabel === "UNASSIGN") {
                // For unassigning, the 'row.id' is the ID of the user_role record itself.
                const userRoleId = row.id;
                if (!userRoleId) {
                    $ctrl.failedAssignments.push({ name: nameForDisplay, message: "Missing assignment ID.", action: actionLabel });
                    continue; // Skip to the next row
                }

                // Use the delete service, which can handle confirmation popups
                response = await $ctrl.dataService.deleteData('user_role', userRoleId, deleteOptions);

                if (response?.result === "cancel") {
                    $ctrl.failedAssignments.push({ name: nameForDisplay, message: "User cancelled.", action: actionLabel });
                    continue; // Skip to the next row
                }
            } else {
                $ctrl.failedAssignments.push({ name: nameForDisplay, message: `Unknown action: ${actionLabel}`, action: actionLabel });
                continue; // Skip to the next row
            }

            // --- 5. Tally Successes and Failures ---
            if (response?.result === "OK") {
                $ctrl.successfulAssignments.push({ name: nameForDisplay, action: actionLabel });
            } else {
                $ctrl.failedAssignments.push({ name: nameForDisplay, message: response?.message || "An unknown error occurred.", action: actionLabel });
            }
        } // End of for...of loop

        await $ctrl.authService.setSaasAuth();

    } else if (targetEntityType === 'scope') {
        // --- [NEW Logic for Assigning SCOPES to ROLES] ---
        if (actionLabel === "ASSIGN" && !$ctrl.currentScopePermission) {
            $ctrl.utilityService.toast("Please select a permission (READ/WRITE) to assign.", "INFO");
            $ctrl.isAssigning = false;
            return;
        }

        for (const row of $ctrl.selectedRows) {
            const nameForDisplay = row.apiEndpoint || "this scope";
            let response;

            if (actionLabel === "ASSIGN") {
                const requestBody = {
                    roleId: primaryEntityId, // The primary entity is the role
                    scopeId: row.id,         // The selected row is the scope
                    permission: $ctrl.currentScopePermission // Use the selected permission
                };
                response = await $ctrl.dataService.sendData('role_scope', 'POST', requestBody, options);

            } else if (actionLabel === "UNASSIGN") {
                const roleScopeId = row.id; // The 'row.id' is the ID of the role_scope assignment
                if (!roleScopeId) {
                    $ctrl.failedAssignments.push({ name: nameForDisplay, message: "Missing assignment ID.", action: actionLabel });
                    continue;
                }

                response = await $ctrl.dataService.deleteData('role_scope', roleScopeId, deleteOptions);

                if (response?.result === "cancel") {
                    $ctrl.failedAssignments.push({ name: nameForDisplay, message: "User cancelled.", action: actionLabel });
                    continue;
                }
            }

            // Tally successes and failures for scopes
            if (response?.result === "OK") {
                $ctrl.successfulAssignments.push({ name: nameForDisplay, action: actionLabel });
            } else {
                $ctrl.failedAssignments.push({ name: nameForDisplay, message: response?.message || "An unknown error occurred.", action: actionLabel });
            }
        }
    }

    // --- 6. Refresh the Data Table ---
    await $ctrl.loadData();

} catch (error) {
    console.error(`An unexpected error occurred during the '${actionLabel}' action:`, error);
    $ctrl.utilityService.toast("An unexpected error occurred. Please try again.", "ERROR");
} finally {
    // This block runs whether the try succeeded or failed, ensuring the loading state is turned off.
    $ctrl.isAssigning = false;
}

const defaultFilter = {
    column: null,
    operation: null,
    target: null,
    query: null,
    columnValues: $ctrl.currentFilter.columnValues
}

$ctrl.currentPage = 1;
$ctrl.hasOperationCompleted = false;
$ctrl.currentFilter = { ...defaultFilter };
$ctrl.selectedRows.length = 0;

$ctrl.loadData();
